package com.yuewei.plm.module.marketwatch;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class MarketPhonePriceProjectionTest {
    @SuppressWarnings("unchecked") @Test void cachedMexicoAndFreshYuanAreBothVisibleWithTheirOwnDatesAndSources(){var row=new LinkedHashMap<String,Object>();var cn=Map.<String,Object>of("verified",true,"amount",1899,"currency","CNY","country","CN","source","中国商城","url","https://cn.test/phone","capturedAt","2026-10-15T00:00:00Z","kind","retail");var mx=new LinkedHashMap<>(cn);mx.put("currency","MXN");mx.put("country","MX");mx.put("source","墨西哥商城");mx.put("url","https://mx.test/phone");mx.put("capturedAt","2026-01-01T00:00:00Z");mx.put("alternativeQuote",cn);row.put("sources",List.of(Map.of("country","MX","price_evidence",mx,"price_error","MX 本次采集失败")));MarketPhonePriceProjection.apply(row);assertThat((List<?>)row.get("prices")).hasSize(2);assertThat((Map<String,Object>)row.get("preferredPrice")).containsEntry("country","MX").containsEntry("stale",true);assertThat(((List<Map<String,Object>>)row.get("prices")).get(1)).containsEntry("country","CN").containsEntry("error",null);}
    @SuppressWarnings("unchecked") @Test void discoveredQuoteKeepsItsOwnProviderAndCountryInsteadOfTheBrokenMonitoringSource(){var row=new LinkedHashMap<String,Object>();var quote=Map.<String,Object>of("verified",true,"amount",1899,"currency","CNY","country","CN","source","OPPO 中国官方商城","url","https://www.opposhop.cn/cn/web/products/1.html","capturedAt","2026-10-15T00:00:00Z","kind","retail");row.put("sources",List.of(Map.of("country","MX","source_name","OPPO 墨西哥监控页","price_evidence",quote)));MarketPhonePriceProjection.apply(row);assertThat((Map<String,Object>)row.get("preferredPrice")).containsEntry("source","OPPO 中国官方商城").containsEntry("country","CN");assertThat(row.get("mexicoPrice")).isNull();assertThat(((List<Map<String,Object>>)row.get("referenceLinks")).get(0)).containsEntry("source","OPPO 中国官方商城");}
    @Test void unverifiedNumbersNeverBecomeFullPricesAndLinksRemainIndependent(){var row=new LinkedHashMap<String,Object>();row.put("sources",List.of(Map.of("price","$395","priceAmount",395,"priceCurrency","MXN","source_url","https://shop.test/phone","source_name","原来源")));MarketPhonePriceProjection.apply(row);assertThat(row.get("mexicoPrice")).isNull();assertThat((List<?>)row.get("referenceLinks")).hasSize(1);}
    @SuppressWarnings("unchecked") @Test void staleVerifiedQuoteAndSourceFailureRetainOriginalCurrencyAndTime(){var q=Map.<String,Object>of("verified",true,"amount",3999,"currency","MXN","url","https://shop.test/phone","capturedAt","2026-01-01T00:00:00Z","specs","4G 128GB");var row=new LinkedHashMap<String,Object>();row.put("sources",List.of(Map.of("country","MX","source_name","官方","price_evidence",q,"price_error","来源失败")));MarketPhonePriceProjection.apply(row);assertThat((Map<String,Object>)row.get("mexicoPrice")).containsEntry("amount",3999).containsEntry("currency","MXN").containsEntry("capturedAt","2026-01-01T00:00:00Z").containsEntry("stale",true).containsEntry("error","来源失败");}
    @SuppressWarnings("unchecked") @Test void historicalApplicationPriceDoesNotAcquireAnInventedCurrency(){var app=new LinkedHashMap<String,Object>();app.put("applicationId",7);app.put("historicalPrice","6999");app.put("referenceUrl","https://example.test/mx/phone");var row=new LinkedHashMap<String,Object>();row.put("coverages",List.of(Map.of("applications",List.of(app))));MarketPhonePriceProjection.apply(row);assertThat(row.get("mexicoPrice")).isNull();assertThat(((List<Map<String,Object>>)row.get("historicalPrices")).get(0)).containsEntry("currency",null);}
    @Test void maintainedArchiveLinksUseTheSameIndependentLinkProjection(){var row=new LinkedHashMap<String,Object>();row.put("coverages",List.of(Map.of("molds",List.of(Map.of("itemId",9,"referenceUrl","https://shop.test/manual-phone")))));MarketPhonePriceProjection.apply(row);assertThat((List<?>)row.get("referenceLinks")).hasSize(1);assertThat(row.get("mexicoPrice")).isNull();}
    @SuppressWarnings("unchecked") @Test void yuanIsPreferredFallbackWithoutPretendingItIsAMexicanQuote(){var row=new LinkedHashMap<String,Object>();var yuan=Map.<String,Object>of("verified",true,"amount",6799,"currency","CNY","url","https://www.apple.com.cn/shop/buy-iphone/iphone-17","capturedAt","2026-10-15T00:00:00Z","specs","iPhone 17 256GB","kind","retail");row.put("sources",List.of(Map.of("country","CN","source_name","苹果中国","price_evidence",yuan)));MarketPhonePriceProjection.apply(row);assertThat((Map<String,Object>)row.get("preferredPrice")).containsEntry("currency","CNY").containsEntry("amount",6799);assertThat(row.get("mexicoPrice")).isNull();}
    @SuppressWarnings("unchecked") @Test void verifiedMexicoQuoteStillWinsOverYuanFallback(){var row=new LinkedHashMap<String,Object>();var quote=Map.<String,Object>of("verified",true,"amount",6799,"currency","CNY","url","https://cn.test/phone","capturedAt","2026-10-15T00:00:00Z","kind","retail");var mx=new LinkedHashMap<>(quote);mx.put("currency","MXN");mx.put("amount",21999);mx.put("url","https://mx.test/phone");row.put("sources",List.of(Map.of("country","CN","source_name","中国","price_evidence",quote),Map.of("country","MX","source_name","墨西哥","price_evidence",mx)));MarketPhonePriceProjection.apply(row);assertThat((Map<String,Object>)row.get("preferredPrice")).containsEntry("currency","MXN").containsEntry("amount",21999);}
    @SuppressWarnings("unchecked") @Test void candidateSourceCountryParticipatesInTheSameCurrencyPreference(){var row=new LinkedHashMap<String,Object>();var quote=Map.<String,Object>of("verified",true,"amount",3999,"currency","MXN","url","https://mx.test/phone","capturedAt","2026-10-15T00:00:00Z","kind","retail");row.put("sources",List.of(Map.of("source_country","MX","source_name","墨西哥候选","price_evidence",quote)));MarketPhonePriceProjection.apply(row);assertThat((Map<String,Object>)row.get("mexicoPrice")).containsEntry("country","MX").containsEntry("currency","MXN");}
    @Test void sameQuoteFromPhoneAndCandidateIsDisplayedOnce(){var row=new LinkedHashMap<String,Object>();var quote=Map.<String,Object>of("verified",true,"amount",5699,"currency","CNY","specs","Xiaomi 17 Pro 12GB+256GB","url","https://www.mi.com/shop/buy?product_id=1","capturedAt","2026-10-15T00:00:00Z","kind","retail");row.put("sources",List.of(Map.of("country","CN","source_name","小米手机来源","price_evidence",quote),Map.of("source_country","CN","source_name","小米候选来源","price_evidence",quote)));MarketPhonePriceProjection.apply(row);assertThat((List<?>)row.get("prices")).hasSize(1);assertThat((List<?>)row.get("referenceLinks")).hasSize(1);}

}
